const textValue = value => typeof value === 'string' && value.length <= 25000;
function validAnalysis(a) {
  if (!a || !textValue(a.id) || !['demo','example','manual','live'].includes(a.mode) || !a.input || !['idea','audience','market','goal'].every(key=>textValue(a.input[key])) || (a.input.context !== undefined && !textValue(a.input.context))) return false;
  if (!a.summary || !['title','thesis','verdict','nextStep'].every(key=>textValue(a.summary[key]))) return false;
  if (!['jtbd','requirements','competitors','counterIdeas','refinements','evidence','sources','limitations'].every(key=>Array.isArray(a[key]) && a[key].length <= 150)) return false;
  if (['jtbd','requirements','counterIdeas','refinements'].some(key=>!a[key].length)) return false;
  const entries = (rows,keys) => rows.every(item=>item && keys.every(key=>textValue(item[key])));
  if (!entries(a.jtbd,['id','situation','motivation','outcome','priority']) || !a.jtbd.every(x=>['high','medium','low'].includes(x.priority))) return false;
  if (!entries(a.requirements,['id','title','why','metric']) || !a.requirements.every(x=>Array.isArray(x.jobIds)&&x.jobIds.every(textValue))) return false;
  if (!entries(a.competitors,['id','name','description','strength','gap','sourceUrl','sourceTitle']) || !a.competitors.every(x=>['direct','indirect','status_quo'].includes(x.type)&&Array.isArray(x.requirementIds)&&x.requirementIds.every(textValue))) return false;
  if (!entries(a.counterIdeas,['id','title','argument','severity','falsificationTest']) || !a.counterIdeas.every(x=>['high','medium'].includes(x.severity))) return false;
  if (!entries(a.refinements,['id','title','audience','problem','differentiation','experiment','successCriterion'])) return false;
  if (!entries(a.evidence,['id','claim','status','sourceUrl','sourceTitle','observedAt','note']) || !a.evidence.every(x=>['supported','hypothesis','contradicted'].includes(x.status))) return false;
  if (!entries(a.sources,['url','title']) || !a.limitations.every(textValue)) return false;
  const it=a.iteration;
  if (!(it && ['continue','test','stop','pivot'].includes(it.decision) && ['rationale','weakestAssumption','changeSummary','selectedRefinementId','newInformation'].every(key=>textValue(it[key])) && Array.isArray(it.remainingRisks) && it.remainingRisks.length<=150 && it.remainingRisks.every(textValue))) return false;
  for (const key of ['jtbd','requirements','competitors','counterIdeas','refinements','evidence']) if (a[key].some(x=>!x.id.trim()) || new Set(a[key].map(x=>x.id)).size!==a[key].length) return false;
  const jobs=new Set(a.jtbd.map(x=>x.id)), requirements=new Set(a.requirements.map(x=>x.id));
  if (a.requirements.some(x=>!x.jobIds.length||x.jobIds.some(id=>!jobs.has(id))) || a.competitors.some(x=>x.requirementIds.some(id=>!requirements.has(id)))) return false;
  return (!it.selectedRefinementId||a.refinements.some(x=>x.id===it.selectedRefinementId))&&(!['continue','pivot'].includes(it.decision)||Boolean(it.selectedRefinementId));
}
let saved={};
