const groupId=a=>a?.loop?.runId||a?.id;
const groupRounds=a=>state.analyses.filter(x=>groupId(x)===groupId(a)).sort((x,y)=>(x.loop?.round||1)-(y.loop?.round||1));
const selectedRefinement=a=>a?.refinements.find(r=>r.id===a.userDirectionId)||a?.refinements.find(r=>r.id===a.iteration?.selectedRefinementId);
const hasNewDirection=a=>Boolean(a?.userDirectionId&&a.userDirectionId!==a.iteration.selectedRefinementId&&a.refinements.some(r=>r.id===a.userDirectionId));
