function investigations(){const groups=new Map();for(const a of state.analyses){const id=groupId(a);if(!groups.has(id))groups.set(id,a);}return [...groups.values()];}
function persist(){try{localStorage.setItem(STORE,JSON.stringify({analyses:state.analyses,draft:state.draft,activeId:state.activeId,mainTab:state.mainTab,workspaceMode:state.workspaceMode,resultTab:state.resultTab,rounds:state.rounds,loopMode:state.loopMode,loopStates:state.loopStates,mvpOptions:state.mvpOptions,running:state.busy}));}catch{toast('Browser storage is unavailable or full. Save a backup to keep your work.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function safeUrl(value){try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)&&!url.username&&!url.password?url.href:'';}catch{return '';}}
const source=(url,title='View source')=>safeUrl(url)?`<a class="source-link" href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${icon('link')}${esc(title)}</a>`:'<span class="small muted">No source recorded</span>';
const tags=values=>values.map(value=>`<span class="tag">${esc(value)}</span>`).join('');
