function render(){
 const a=current();if(!a&&!state.busy)state.workspaceMode='compose';
 $('#app').innerHTML=`<header class="app-header"><div class="header-inner"><a class="brand" href="#" data-main="workspace" aria-label="Idea Lab workspace"><span class="brand-mark">${icon('flask')}</span>idea<span>lab</span></a><nav class="main-nav" aria-label="Main navigation">${mainTabs.map(([id,label])=>`<button data-main="${id}" class="${state.mainTab===id?'active':''}" ${state.mainTab===id?'aria-current="page"':''} ${state.busy&&id==='examples'?'disabled':''}>${label}</button>`).join('')}</nav><button class="settings-gear" data-settings ${state.busy?'disabled':''} aria-label="Connection settings" title="Connection settings">${icon('settings')}</button></div></header><main id="main" tabindex="-1">${state.error?`<div class="notice error" role="alert">${esc(state.error)}</div>`:''}${state.mainTab==='workspace'?workspaceView(a):state.mainTab==='examples'?examplesView():howView()}</main><footer class="app-footer"><span>Better questions. A sharper idea.</span><span>Saved in this browser · Idea Lab</span></footer>`;
 bind();
}
function moreMenu(a){return `<details class="more-menu"><summary>More ${icon('settings')}</summary><div><button data-import ${state.busy?'disabled':''}>Restore a backup</button><button data-export ${!a?'disabled':''}>Save investigation backup</button></div></details>`;}
