function composeView(a){return `<div class="workspace-heading"><div><span class="eyebrow">START WITH A POSSIBILITY</span><h1>Make your idea <em>more specific.</em></h1><p>See who needs it, what already exists, and what could make it fail.<br class="desktop-break"> Get a sharper direction and a practical first test.</p></div>${moreMenu(a)}</div><section class="idea-panel"><form id="idea-form"><label class="large-label" for="idea">What would you like to build?</label><textarea id="idea" name="idea" rows="5" required minlength="20" maxlength="6000" placeholder="For example: a team chat app for people working different shifts…" ${state.busy?'disabled':''}>${esc(state.draft.idea)}</textarea><div class="input-hint"><span>A rough idea is enough. Tell us who it could help and why.</span><span id="char-count">${state.draft.idea.length} / 6000</span></div><details class="optional-details"><summary>Add audience, market or context <span>Optional</span></summary><div class="form-grid"><div><label for="audience">Who is it for?</label><input id="audience" name="audience" maxlength="500" value="${esc(state.draft.audience)}" placeholder="For example, managers of small shops" ${state.busy?'disabled':''}></div><div><label for="market">Where would you start?</label><input id="market" name="market" maxlength="200" value="${esc(state.draft.market)}" placeholder="For example, the UK" ${state.busy?'disabled':''}></div></div><label for="goal">What do you want to find out?</label><input id="goal" name="goal" maxlength="1200" value="${esc(state.draft.goal)}" ${state.busy?'disabled':''}><label for="iteration-context">What you have already learned</label><textarea id="iteration-context" name="context" maxlength="8000" rows="4" placeholder="What have you already tried, observed or ruled out?" ${state.busy?'disabled':''}>${esc(state.draft.context)}</textarea><p class="small muted">These observations will accompany the idea. Their limits stay visible.</p></details>${loopControls()}<div class="form-submit"><button type="submit" class="button primary" ${state.busy?'disabled':''}>${state.busy?'<span class="spinner"></span>Working on your idea…':`${icon('refine')}Improve my idea`}</button><span>${state.loopMode==='auto'?`Up to ${state.rounds} rounds automatically`:'One round, then you choose the next step'}. Stop at any time.</span></div><p class="connection-hint">${state.settingsReady?connectionReady()?'Using '+esc(providerNames[state.settings.provider])+'.':state.settings.runtime==='hosted'?'Add your API key in Settings.':'Add your AI connection to get started.':'Checking your connection…'} <button type="button" class="text-link" data-settings ${state.busy?'disabled':''}>Connection settings</button></p></form></section><div class="workspace-intro-links"><button class="text-link" data-main="how">How does this work?</button><span>or</span><button class="text-link" data-main="examples" ${state.busy?'disabled':''}>Explore a finished example</button></div>${investigations().length?`<section class="saved-work">${heading('Your saved investigations')}<div class="history-list">${investigations().map(item=>`<button data-open="${esc(item.id)}" class="history-item" ${state.busy?'disabled':''}><span>${icon(item.mode==='example'?'library':'folder')}</span><span><strong>${esc(item.loop?.title||item.summary.title)}</strong><small>${groupRounds(item).length} ${groupRounds(item).length===1?'round':'rounds'} · ${esc(modeLabel(item))} · ${date(item.createdAt)}</small></span><span class="history-open">Open</span></button>`).join('')}</div></section>`:''}`;}
function resultsView(a){const rounds=groupRounds(a),index=rounds.findIndex(item=>item.id===a.id),r=selectedRefinement(a),story=storyFor(a),isFinal=index===rounds.length-1;return `<div class="results-toolbar"><button class="text-link" data-new ${state.busy?'disabled':''}>${icon('plus')}New idea</button><div>${!state.busy?`<button class="text-link" data-edit>Revise as a new idea</button>`:''}${moreMenu(a)}</div></div><div class="result-intro"><span class="eyebrow">${esc(modeLabel(a))} · ROUND ${index+1}${isFinal?' · LATEST':''}</span><h1>${esc(a.summary.title)}</h1><p>${esc(a.summary.thesis)}</p></div>${provenanceNotice(a)}<div class="round-history" aria-label="Choose a completed research round">${rounds.map((item,i)=>`<button data-round="${esc(item.id)}" class="${item.id===a.id?'selected':''}" aria-pressed="${item.id===a.id}"><span>Round ${i+1} · saved</span><strong>${esc(previewText(item.summary.title,65))}</strong><small>${esc(decisionText(item.iteration.decision))}</small></button>`).join('')}</div>${loopPanel(a,rounds,index)}<nav class="result-tabs" aria-label="Investigation sections">${[['overview','Overview'],['research','Research'],['build','Build brief']].map(([id,label])=>`<button data-result-tab="${id}" class="${state.resultTab===id?'active':''}" ${state.resultTab===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><section class="result-content">${state.resultTab==='overview'?overviewView(a,r,story,isFinal):state.resultTab==='research'?researchView(a):buildView(a)}</section>`;}
const previewText=(value,limit=360)=>String(value||'').length>limit?`${String(value).slice(0,limit)}…`:String(value||'');
const loopMeta=a=>state.loopStates[groupId(a)]||{status:a.iteration.decision,mode:'review',plannedRounds:a.loop?.maxRounds||state.rounds};
const freshFindings=a=>a.evidence.filter(item=>item.userProvided&&item.addedAfterRound===a.id);
function loopControls(){return `<fieldset class="loop-controls"><legend>How would you like to refine it?</legend><div class="loop-options"><label class="loop-option ${state.loopMode==='auto'?'chosen':''}"><input type="radio" name="loop-mode" value="auto" ${state.loopMode==='auto'?'checked':''} ${state.busy?'disabled':''}><span><strong>Automatic</strong><small>The AI runs useful rounds, then explains why it paused.</small></span></label><label class="loop-option ${state.loopMode==='review'?'chosen':''}"><input type="radio" name="loop-mode" value="review" ${state.loopMode==='review'?'checked':''} ${state.busy?'disabled':''}><span><strong>Review each round</strong><small>You read the result and choose when to run the next round.</small></span></label></div><div class="round-budget"><label for="round-count">${state.loopMode==='auto'?'Run up to':'Plan up to'}</label><select id="round-count" ${state.busy?'disabled':''}>${[2,3,4,5].map(n=>`<option value="${n}" ${state.rounds===n?'selected':''}>${n} rounds</option>`).join('')}</select><span>Each round revisits the chosen direction with the earlier evidence and objections.</span></div><p class="small muted">The AI pauses early when a customer test is more useful than another search. Every new research round uses your AI connection.</p></fieldset>`;}
function loopPanel(a,rounds,index){
 const number=a.loop?.round||index+1,latest=index===rounds.length-1,meta=loopMeta(a),r=selectedRefinement(a),findings=freshFindings(a),example=a.mode==='example';
 let title='',description='',button='',action='',secondary='',cost='';
 if(!latest){title=`You are viewing saved round ${number}`;description=example?'Follow the completed example one round at a time. No AI calls are made.':'This is an earlier snapshot. Continue from the latest round to keep the investigation in order.';button=example?`See round ${index+2}`:'Go to the latest round';action=`data-round="${esc(example?rounds[index+1].id:rounds.at(-1).id)}"`;}
 else if(example){title='You have reached the end of this example';description='These three authored rounds show how an idea can change. Start your own variation to research a real idea with your AI connection.';button='Try your own version';action=`data-variation="${esc(a.loop.exampleId)}"`;}
 else if(state.busy){title=`Round ${number} is saved`;description='The next round is running. You can read completed work while the AI continues.';}
 else if(number>=5){title='Five rounds saved. Choose a real next step.';description='Copy the test plan and gather a finding. To explore a different premise, start a new investigation with the learning you have already saved.';button='Start from this version';action='data-fork-current';}
 else if(['paused','error'].includes(meta.status)){title=`Paused before round ${number+1}`;description='Your completed rounds are safe. Continue from the next round, with the chosen direction and earlier evidence.';button=meta.status==='error'?`Retry round ${number+1}`:'Resume research';action='data-continue';cost=meta.mode==='auto'?`Resumes automatic research up to round ${meta.plannedRounds}. It can still pause early.`:'Runs one new round. Saved rounds are not repeated.';}
 else if(['test','stop'].includes(a.iteration.decision)&&!findings.length&&!hasNewDirection(a)){title=a.iteration.decision==='test'?'A real-world finding is the next step':'Pause and reconsider the premise';description=a.iteration.decision==='test'?'More AI rounds cannot answer this uncertainty. Use the test plan below, then record what actually happened to refine the idea with new information.':'The AI found a reason to stop. Add a concrete finding that changes the premise before asking it to reassess.';button=a.iteration.decision==='test'?'Add a test finding':'Add evidence to reassess';action='data-add-evidence';secondary=`<button class="text-link" data-result-tab="research" data-directions>Try a different direction</button>`;}
 else{const withFinding=findings.length&&['test','stop'].includes(a.iteration.decision);title=hasNewDirection(a)?'Your alternative is ready for the next round':withFinding?'Your new finding is ready to use':meta.status==='limit'?'Your planned rounds are complete':`Round ${number} complete. Ready for round ${number+1}.`;description=hasNewDirection(a)?'You selected a different premise to explore. It will be researched in this same investigation; customer demand is still unproven.':withFinding?'The next round will challenge the idea using your finding and the earlier objections. A finding is user-reported until independently checked.':meta.status==='limit'?'Review the learning before spending on more research. You can explicitly run one more round in this same investigation.':'Review what changed below, then let the AI examine the proposed next direction.';button=hasNewDirection(a)?'Research this direction':withFinding?'Refine with this finding':`Run round ${number+1}`;action='data-continue';cost='Runs one new round using your AI connection. Earlier rounds stay saved.';}
 const analyzedLabel='Idea actually analyzed in this round',directionLabel=hasNewDirection(a)?'Your choice for the next round':['test','stop'].includes(a.iteration.decision)?'Proposed direction to test':'Direction proposed for the next round';
 return `<section class="loop-panel" aria-labelledby="loop-title"><div class="loop-panel-heading"><div><span class="eyebrow">${example?'FOLLOW THE EXAMPLE':'YOUR NEXT STEP'} · ${rounds.length} ${rounds.length===1?'ROUND':'ROUNDS'} SAVED</span><h2 id="loop-title" tabindex="-1">${esc(title)}</h2><p>${esc(description)}</p></div>${button?`<div class="loop-action"><button class="button primary" ${action} ${state.busy?'disabled':''}>${icon(example?'loop':'refine')}${esc(button)}</button>${secondary}${cost?`<small>${esc(cost)}</small>`:''}</div>`:''}</div><div class="round-premises"><div><strong>${analyzedLabel}</strong><p>${esc(previewText(a.input.idea,420))}</p></div><div><strong>${directionLabel}</strong><p>${r?esc(r.title):'No next direction was selected. The current premise needs a test or a rethink.'}</p>${r?`<small>This proposal has not yet been validated${latest?' or analyzed in a following round':''}.</small>`:''}</div></div><div class="round-changes"><p><strong>${number===1?'Starting point':'What changed'}</strong>${esc(a.iteration.changeSummary)}</p><p><strong>New information and its limits</strong>${esc(a.iteration.newInformation)}</p></div><details class="loop-explanation"><summary>Why did the AI choose this next step?</summary><p>${esc(a.iteration.rationale)}</p><p>Automatic mode continues only for a useful research question or a different direction. A test or stop decision pauses it. The round limit bounds each automatic run; it is not a promise of improvement.</p></details></section>`;
}
function testPlanView(a,r){return `<section class="test-kit"><div class="section-row"><div><span class="eyebrow">FROM AI RESEARCH TO SOMETHING YOU CAN CHECK</span><h2>A small test before a big build</h2></div><span class="tag">Proposed · not performed</span></div><p>${esc(r?.experiment||a.summary.nextStep)}</p><div class="test-threshold"><strong>Decide what would count as success first</strong><p>${esc(r?.successCriterion||'Write an observable pass/fail threshold before the test. A compliment or a lack of competitors does not establish demand.')}</p></div><div class="test-actions"><button class="button" data-copy-test>${icon('flask')}Copy test plan</button>${a.mode==='example'?`<button class="text-link" data-variation="${esc(a.loop?.exampleId)}">Try your own test</button>`:`<button class="text-link" data-add-evidence ${state.busy||groupRounds(a).at(-1)?.id!==a.id?'disabled':''}>${groupRounds(a).at(-1)?.id===a.id?'Add what you learned':'Record findings on the latest round'}</button>`}</div><details class="test-plan-details"><summary>Read the plan and customer questions</summary><label class="sr-only" for="test-plan-output">Proposed real-world test plan</label><textarea id="test-plan-output" readonly rows="14">${esc(generateTestPlan(a))}</textarea><button class="text-link" data-save-test>Download test plan</button></details><p class="small muted">Includes questions to ask, what to record and how to decide. Creating this plan makes no AI call.</p></section>`;}
function openEvidence(){if(state.busy)return;const a=current();if(!a)return;if(a.mode==='example'){toast('Start your own variation to record findings for a live investigation.');return;}if(groupRounds(a).at(-1)?.id!==a.id){toast('Go to the latest round before recording a finding for the next refinement.');return;}$('#finding-target').textContent=`For round ${a.loop?.round||groupRounds(a).length}: ${previewText(a.input.idea,200)}`;$('#evidence-dialog').showModal();}
function forkCurrent(){if(state.busy)return;const a=current();if(!a)return;state.draft=buildIterationInput(a);state.activeId=null;state.workspaceMode='compose';state.error='';state.notice='';navigate('workspace');toast('A new investigation is ready, carrying the previous learning. Review the premise before starting.');}

function provenanceNotice(a){return a.mode==='example'?`<div class="notice sample-note">${icon('library')}<span><strong>A worked example, not proof of demand.</strong> Product capabilities are sourced. No customer interviews, sales or pilot results have been collected.</span></div>`:a.mode==='demo'?`<div class="notice sample-note">${icon('flask')}<span>Illustrative demo. No market research was performed.</span></div>`:a.mode==='manual'?`<div class="notice"><span>Restored from a backup. Review the sources and observations before relying on them.</span></div>`:`<p class="research-note">Public sources help explain alternatives. The next real test must establish whether people need this and will act on it.</p>`;}
function overviewView(a,r,story,isFinal){const who=isFinal&&story?story.whoItServes:r?.audience||a.input.audience,why=isFinal&&story?story.whyItCouldWin:r?.differentiation||a.summary.thesis,risk=isFinal&&story?story.biggestRisk:a.iteration.weakestAssumption,test=isFinal&&story?story.firstTest:r?.experiment||a.summary.nextStep;return `<div class="plain-summary"><article><span class="summary-icon">${icon('jobs')}</span><h2>Who it serves</h2><p>${esc(who||'The first audience still needs to be defined.')}</p></article><article><span class="summary-icon">${icon('refine')}</span><h2>Why it could be useful</h2><p>${esc(why)}</p></article><article><span class="summary-icon amber">${icon('critique')}</span><h2>The riskiest assumption</h2><p>${esc(risk)}</p></article><article><span class="summary-icon">${icon('flask')}</span><h2>The next real test</h2><p>${esc(test)}</p></article></div>${testPlanView(a,r)}${story?storyComparison(story):''}<section class="overview-section">${heading('The real need','What the person is trying to achieve, before choosing features.')}<div class="job-list plain">${a.jtbd.slice(0,3).map(j=>`<article><p class="job-situation">${esc(j.situation)}</p><h3>${esc(j.motivation)}</h3><p>${esc(j.outcome)}</p></article>`).join('')}</div></section><section class="overview-section">${heading('What could break the idea','The strongest objections should survive every round of refinement.')}<div class="objection-list">${a.counterIdeas.slice(0,3).map(c=>`<article><span>${icon('critique')}</span><div><h3>${esc(c.title)}</h3><p>${esc(c.argument)}</p><details><summary>How to test this objection</summary><p>${esc(c.falsificationTest)}</p></details></div></article>`).join('')}</div></section><section class="next-test"><div><span class="eyebrow">A DECISION, NOT A VERDICT</span><h2>${esc(decisionText(a.iteration.decision))}</h2><p>${esc(a.iteration.rationale)}</p>${r?.successCriterion?`<p class="criterion"><strong>Proposed test threshold</strong>${esc(r.successCriterion)}</p>`:''}</div><button class="button" data-result-tab="build">Optional: prepare a build brief</button></section><details class="round-learning"><summary>What changed in this round?</summary><dl><dt>The change</dt><dd>${esc(a.iteration.changeSummary)}</dd><dt>New information</dt><dd>${esc(a.iteration.newInformation)}</dd><dt>What remains uncertain</dt><dd><ul>${a.iteration.remainingRisks.map(value=>`<li>${esc(value)}</li>`).join('')}</ul></dd></dl></details>`;}
function storyComparison(story){return `<details class="overview-section example-comparison comparison-details"><summary>How this differs from the obvious clone</summary><div class="comparison-table-wrap"><table><thead><tr><th scope="col">The choice</th><th scope="col">What already exists</th><th scope="col">The proposed direction</th></tr></thead><tbody>${story.comparison.map(row=>`<tr><th scope="row">${esc(row.dimension)}</th><td>${esc(row.incumbent)}</td><td>${esc(row.proposal)}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Proposed advantages remain hypotheses. The Research section records their sources and limits.</p></details>`;}
function researchView(a){return `${heading('The reasoning and its sources','Open a section when you want to inspect the detail. A citation can support a capability; it does not establish demand.')}<details class="research-group"><summary><span>${icon('jobs')}Needs and requirements</span><small>${a.jtbd.length} jobs · ${a.requirements.length} requirements</small></summary><div class="details-content"><h3>Jobs to be done</h3><p class="small muted">A job describes the progress a person wants to make. IDs connect that need to a requirement.</p>${a.jtbd.map(j=>`<article class="research-item"><div class="item-heading"><span class="tag">${esc(j.id)}</span><span class="small muted">${esc(j.priority)} priority</span></div><p>${esc(j.situation)}</p><h4>${esc(j.motivation)}</h4><p>${esc(j.outcome)}</p></article>`).join('')}<h3 class="subheading">What the software must achieve</h3>${a.requirements.map(r=>`<article class="research-item"><div class="item-heading"><h4>${esc(r.title)}</h4>${tags([r.id,...r.jobIds])}</div><p>${esc(r.why)}</p><div class="metric"><strong>How to check it</strong>${esc(r.metric)}</div></article>`).join('')}</div></details><details class="research-group"><summary><span>${icon('map')}Alternatives and competition</span><small>${a.competitors.length} alternatives</small></summary><div class="details-content">${a.competitors.map(c=>`<article class="research-item"><div class="item-heading"><h3>${esc(c.name)}</h3><span class="tag">${esc({direct:'Direct competitor',indirect:'Indirect alternative',status_quo:'Current habit'}[c.type])}</span></div><p>${esc(c.description)}</p><div class="comparison-columns"><div><strong>Why it could win</strong><p>${esc(c.strength)}</p></div><div><strong>Possible gap to check</strong><p>${esc(c.gap)}</p></div></div><div class="item-footer">${source(c.sourceUrl,c.sourceTitle||'View the source')}<div>${tags(c.requirementIds)}</div></div></article>`).join('')||'<p>No researched alternatives were recorded. This is a limitation, not evidence of an empty market.</p>'}</div></details><details class="research-group" id="directions"><summary><span>${icon('critique')}All objections and other directions</span><small>${a.counterIdeas.length} objections · ${a.refinements.length} directions</small></summary><div class="details-content">${a.counterIdeas.map(c=>`<article class="research-item"><div class="item-heading"><h3>${esc(c.title)}</h3><span class="badge ${c.severity==='high'?'rose':'amber'}">${esc(c.severity)} risk</span></div><p>${esc(c.argument)}</p><div class="metric"><strong>The test</strong>${esc(c.falsificationTest)}</div></article>`).join('')}<h3 class="subheading">Different directions considered</h3>${a.refinements.map(r=>`<article class="research-item"><div class="item-heading"><h3>${esc(r.title)}</h3><span class="tag">${a.userDirectionId===r.id?'Your next direction':a.iteration.selectedRefinementId===r.id?'AI recommendation':esc(r.id)}</span></div><p><strong>For:</strong> ${esc(r.audience)}</p><p>${esc(r.problem)}</p><p>${esc(r.differentiation)}</p><div class="metric"><strong>Proposed test</strong>${esc(r.experiment)}<p>${esc(r.successCriterion)}</p></div><button class="text-link" data-refine="${esc(r.id)}" ${state.busy||a.userDirectionId===r.id?'disabled':''}>${a.userDirectionId===r.id?'Selected for the next round':a.mode==='example'||groupRounds(a).at(-1)?.id!==a.id||(a.loop?.round||1)>=5?'Explore as a new investigation':'Use for the next round'}</button></article>`).join('')}</div></details><details class="research-group"><summary><span>${icon('evidence')}Evidence and limitations</span><small>${a.evidence.length} recorded claims</small></summary><div class="details-content"><div class="section-row"><h3>Evidence ledger</h3><button class="button small-button" data-add-evidence ${state.busy||a.mode==='example'||groupRounds(a).at(-1)?.id!==a.id?'disabled':''}>Add an observation</button></div><p class="small muted">Observations you add remain user-reported. They will accompany future rounds.</p>${a.evidence.map(e=>`<article class="research-item"><div class="item-heading"><span class="badge ${e.status==='supported'?'green':e.status==='contradicted'?'rose':'amber'}">${esc(e.userProvided?'User-reported observation':{supported:'Source-supported claim',hypothesis:'Hypothesis',contradicted:'Contrary evidence'}[e.status])}</span><span class="small muted">${esc(e.observedAt||'Not observed yet')}</span></div><h4>${esc(e.claim)}</h4><p>${esc(e.note)}</p>${source(e.sourceUrl,e.sourceTitle||'View evidence')}</article>`).join('')}<h3 class="subheading">What this research cannot tell us</h3><ul class="limitations">${a.limitations.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>${a.sources.length?`<h3 class="subheading">Cited sources</h3><div class="sources">${a.sources.map(item=>source(item.url,item.title||item.url)).join('')}</div>`:''}</div></details>`;}
function buildView(a){return `${heading('A focused brief for your coding agent','Copy this into Codex or Claude Code when you are ready to build the smallest useful test.')}<div class="notice">${icon('code')}<span><strong>This prepares the instructions; it does not build the product here.</strong> The brief includes the user need, the smallest useful version, checks to run, and what is still unproven.</span></div><div class="build-panel"><details class="optional-details"><summary>Adjust the build brief <span>Optional</span></summary><form id="mvp-form"><div class="form-grid"><div><label for="mvp-stack">Preferred technology</label><input id="mvp-stack" name="stack" maxlength="1200" value="${esc(state.mvpOptions.stack)}" placeholder="Leave empty for the agent to choose"></div><div><label for="mvp-platform">Where it will run</label><input id="mvp-platform" name="platform" maxlength="800" value="${esc(state.mvpOptions.platform)}" placeholder="For example, a web app"></div></div><label for="mvp-notes">Anything else to consider?</label><textarea id="mvp-notes" name="notes" rows="3" maxlength="4000" placeholder="Your preferences, constraints, or a smaller first test…">${esc(state.mvpOptions.notes)}</textarea></form></details><div class="section-row prompt-actions"><h3>Ready to copy</h3><div><button class="button primary small-button" data-copy-mvp>Copy build brief</button><button class="button small-button" data-save-mvp>Download .txt</button></div></div><label class="sr-only" for="mvp-output">MVP build brief</label><textarea id="mvp-output" class="prompt-output" readonly rows="17" spellcheck="false">${esc(generateMvpPrompt(a,state.mvpOptions))}</textarea><p class="small muted">No AI call is made when you generate or copy this brief. It asks for a local, single-container application and honest test results.</p></div>`;}
function examplesView(){return `<div class="page-heading"><span class="eyebrow">SEE HOW AN IDEA GETS SHARPER</span><h1>From a generic clone<br>to a <em>specific starting point.</em></h1><p>These three examples show the change in thinking, what incumbents already do, and the evidence still missing.</p></div><div class="notice sample-note">${icon('library')}<span>These are authored examples, not completed AI runs or proven businesses. Linked sources establish product capabilities. Customer demand remains untested.</span></div><div class="example-list">${examples.map((item,index)=>{const story=item.story;return `<article class="example-card"><div class="example-title"><span class="example-symbol symbol-${index}">${icon(index===0?'map':index===1?'jobs':'clock')}</span><div><span class="eyebrow">${esc(item.category)} · THREE ROUNDS</span><h2>${esc(item.title)}</h2></div></div><div class="before-after"><div><span>Starting idea</span><h3>${esc(story?.startingPoint||item.description)}</h3></div><span class="diagram-arrow" aria-hidden="true">→</span><div><span>Sharper direction</span><h3>${esc(story?.finalWedge||item.description)}</h3></div></div><div class="example-explainer"><div><strong>The turning point</strong><p>${esc(story?.turningPoint||item.description)}</p></div><div><strong>What could kill it</strong><p>${esc(story?.biggestRisk||'Demand still needs a real-world test.')}</p></div></div><details class="example-story"><summary>See the three changes in thinking</summary><ol>${(story?.learningPath||[]).map(step=>`<li><h4>${esc(step.title)}</h4><p>${esc(step.change)}</p><p class="small muted">${esc(step.why)}</p></li>`).join('')}</ol></details><div class="example-actions"><button class="button primary" data-example="${esc(item.id)}" ${state.busy?'disabled':''}>Explore this example</button><button class="button" data-variation="${esc(item.id)}" ${state.busy?'disabled':''}>Try your own variation</button></div></article>`;}).join('')}</div>`;}
const howSteps=[
 {title:'Understand the real need',short:'Understand',icon:'jobs',hat:'The listener',does:'The AI starts with what a person is trying to achieve. It turns that into a few results the software would need to deliver.',example:'Instead of “send more messages”, a shift manager needs the next team to know which tasks are unfinished and who owns each one.',limit:'These needs begin as hypotheses. A person doing the job still needs to confirm them.'},
 {title:'Research the alternatives',short:'Research',icon:'map',hat:'The researcher',does:'It looks at existing products, services and everyday workarounds. It compares them with the needs from the first step.',example:'Slack, Teams, a paper handover book, or a verbal briefing might already solve much of the problem. The AI checks what each can do.',limit:'A product page can support a feature claim. It cannot tell us whether customers want our idea.'},
 {title:'Challenge it, then invent alternatives',short:'Challenge & invent',icon:'critique',hat:'The skeptic and the inventor',does:'It looks for reasons the idea could fail, then explores different users, business mechanisms and ways to reach them.',example:'“Another chat app” becomes a handover check for small shop teams, or a setup service using their current tools. These are different bets, not a longer feature list.',limit:'A clever alternative is still only a proposal. The AI must not invent customer interviews, sales or test results.'},
 {title:'Compare, choose, and repeat if useful',short:'Compare & repeat',icon:'loop',hat:'The decision maker',does:'Choose Automatic to let useful rounds run up to your limit, or Review each round to advance yourself. The Run next round button keeps the same investigation, evidence and objections.',example:'If current tools already handle messages, the next round asks whether missing acknowledgement of unfinished work creates a costly problem.',limit:'More rounds do not create more evidence by themselves. The loop stops when another search adds little, the idea fails, or customers must be involved.'},
 {title:'Leave with a direction and a first test',short:'A test & build brief',icon:'code',hat:'The experiment planner',does:'The result explains who the idea serves, why it could help, its biggest risk, and a small real-world test. You can copy a focused brief into a coding agent.',example:'Test a simple handover checklist with three consenting shop teams before building a new communication platform. Set a threshold before seeing the outcome.',limit:'The build brief is an instruction for a coding agent. It does not build or deploy anything inside this research app.'},
];
function howView(){const step=howSteps[state.howStep];return `<div class="page-heading"><span class="eyebrow">THE PROCESS, WITHOUT THE MYSTERY</span><h1>One idea. <em>Five useful questions.</em></h1><p>The AI takes different roles to examine your idea. You can inspect what changed and stop the work at any time.</p></div><section class="how-diagram"><div class="diagram-start"><span>Your starting idea</span><strong>“A chat app for teams working different shifts.”</strong></div><div class="diagram-flow" role="group" aria-label="Explore the five steps">${howSteps.map((item,index)=>`<button class="diagram-step ${state.howStep===index?'selected':''}" data-how-step="${index}" aria-pressed="${state.howStep===index}" aria-controls="how-detail"><span>${icon(item.icon)}</span><strong>${esc(item.short)}</strong></button>${index<howSteps.length-1?'<span class="diagram-connector" aria-hidden="true">→</span>':''}`).join('')}</div><div class="diagram-return"><svg viewBox="0 0 1000 38" preserveAspectRatio="none" aria-hidden="true"><path d="M735 0v13q0 12-12 12H105q-12 0-12-12V2"/><path d="m87 8 6-6 6 6"/></svg><p>Next round → examine the selected direction again, carrying the evidence and objections forward.</p></div><div id="how-detail" class="how-detail" aria-live="polite"><div><span class="eyebrow">STEP ${state.howStep+1} · ${esc(step.hat)}</span><h2>${esc(step.title)}</h2><p>${esc(step.does)}</p></div><div class="how-example"><strong>For the shift-team example</strong><p>${esc(step.example)}</p></div><p class="how-limit">${icon('evidence')}<span>${esc(step.limit)}</span></p></div></section><div class="how-facts"><article><h2>One AI, different hats</h2><p>These are roles given to the same AI connection, not independent teams or a panel of experts. Each round has two passes: first the need and requirements, then research, critique and new directions.</p></article><article><h2>You always know the next step</h2><p>Use Run next round to continue the same investigation. If research pauses for a customer test, copy the test plan, try it, and add a finding. Then refine with that finding. You can resume interrupted work without repeating saved rounds.</p></article><article><h2>Sources and demand answer different questions</h2><p>A source can show that a competitor offers a feature. Demand requires real behavior: people using a solution, accepting a priced pilot, or making a credible commitment.</p></article></div><div class="how-cta"><button class="button primary" data-main="workspace">Start with your idea</button><button class="button" data-main="examples" ${state.busy?'disabled':''}>See finished examples</button></div>`;}

function navigate(tab){if(state.busy&&tab==='examples')return;state.mainTab=tab;persist();render();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function saveRound(a){state.analyses=[a,...state.analyses.filter(x=>x.id!==a.id)];const retained=new Set(investigations().slice(0,12).map(groupId));state.analyses=state.analyses.filter(x=>retained.has(groupId(x)));state.loopStates=Object.fromEntries(Object.entries(state.loopStates).filter(([id])=>retained.has(id)));state.activeId=a.id;persist();}
function openRounds(rounds,title,exampleId=''){const runId=uid(),ids=new Map(rounds.map(item=>[item.id,uid()]));let parentId='';rounds.forEach((item,index)=>{const id=ids.get(item.id);saveRound({...item,id,evidence:item.evidence.map(e=>({...e,...(e.addedAfterRound?{addedAfterRound:ids.get(e.addedAfterRound)||e.addedAfterRound}:{})})),loop:{runId,round:index+1,maxRounds:rounds.length,parentId,title,...(exampleId?{exampleId}:{})}});parentId=id;});state.activeId=exampleId?groupRounds(current())[0].id:groupRounds(current()).at(-1).id;state.workspaceMode='results';state.resultTab='overview';state.error='';state.notice='';navigate('workspace');}
function bind(){
 document.querySelectorAll('[data-main]').forEach(el=>el.addEventListener('click',event=>{event.preventDefault();navigate(el.dataset.main);}));
 document.querySelectorAll('[data-settings]').forEach(el=>el.addEventListener('click',openSettings));
 document.querySelectorAll('[data-import]').forEach(el=>el.addEventListener('click',()=>{$('#import-error').textContent='';$('#import-dialog').showModal();}));
 document.querySelectorAll('[data-export]').forEach(el=>el.addEventListener('click',exportInvestigation));
 document.querySelectorAll('[data-new]').forEach(el=>el.addEventListener('click',()=>{if(state.busy)return;state.activeId=null;state.draft=defaultDraft();state.workspaceMode='compose';state.error='';state.notice='';navigate('workspace');$('#idea').focus();}));
 document.querySelectorAll('[data-open]').forEach(el=>el.addEventListener('click',()=>{if(state.busy)return;state.activeId=el.dataset.open;state.workspaceMode='results';state.resultTab='overview';state.error='';state.notice='';navigate('workspace');}));
 document.querySelectorAll('[data-example]').forEach(el=>el.addEventListener('click',()=>{if(state.busy)return;const example=createExample(el.dataset.example);openRounds(example.rounds,example.title,el.dataset.example);}));
 document.querySelectorAll('[data-variation]').forEach(el=>el.addEventListener('click',()=>{if(state.busy)return;const sample=examples.find(item=>item.id===el.dataset.variation);state.draft={...defaultDraft(),...sample.story.suggestedInput};state.activeId=null;state.workspaceMode='compose';state.error='';navigate('workspace');toast('Example starting point loaded. Change the idea to make it your own.');$('#idea').focus();}));
 document.querySelectorAll('[data-round]').forEach(el=>el.addEventListener('click',()=>{state.activeId=el.dataset.round;persist();render();}));
 document.querySelectorAll('[data-result-tab]').forEach(el=>el.addEventListener('click',()=>{state.resultTab=el.dataset.resultTab;persist();render();if(el.hasAttribute('data-directions')){const directions=$('#directions');if(directions){directions.open=true;directions.scrollIntoView({block:'start',behavior:'instant'});}}}));
 document.querySelectorAll('[data-how-step]').forEach(el=>el.addEventListener('click',()=>{state.howStep=Number(el.dataset.howStep);render();$(`[data-how-step="${state.howStep}"]`).focus({preventScroll:true});}));
 document.querySelectorAll('[data-refine]').forEach(el=>el.addEventListener('click',()=>{if(state.busy)return;const a=current();if(a.mode==='example'||groupRounds(a).at(-1)?.id!==a.id||(a.loop?.round||1)>=5){state.draft=buildIterationInput({...a,userDirectionId:el.dataset.refine});state.activeId=null;state.workspaceMode='compose';state.error='';navigate('workspace');toast('This direction is ready for a new investigation, with the previous learning.');return;}a.userDirectionId=el.dataset.refine;state.resultTab='overview';state.error='';persist();render();$('#loop-title')?.focus();toast('Direction selected. Review it, then run the next round when ready.');}));
 $('[data-edit]')?.addEventListener('click',()=>{if(state.busy)return;state.draft=buildIterationInput(current());state.workspaceMode='compose';state.error='';navigate('workspace');});
 $('[data-stop]')?.addEventListener('click',()=>{state.run.stopRequested=true;runController?.abort();toast('Stopping. Completed rounds remain saved.');});
 $('#idea-form')?.addEventListener('input',event=>{if(Object.hasOwn(defaultDraft(),event.target.name)){state.draft[event.target.name]=event.target.value;persist();}if($('#char-count'))$('#char-count').textContent=`${state.draft.idea.length} / 6000`;});
 $('#round-count')?.addEventListener('change',event=>{state.rounds=Number(event.target.value);persist();});
 $('#idea-form')?.addEventListener('submit',startResearch);
 document.querySelectorAll('[name="loop-mode"]').forEach(el=>el.addEventListener('change',()=>{state.loopMode=el.value;persist();render();}));
 $('[data-continue]')?.addEventListener('click',continueResearch);
 $('[data-fork-current]')?.addEventListener('click',forkCurrent);
 document.querySelectorAll('[data-add-evidence]').forEach(el=>el.addEventListener('click',openEvidence));
 $('[data-copy-test]')?.addEventListener('click',()=>copyText(generateTestPlan(current()),$('#test-plan-output'),'Test plan copied.'));
 $('[data-save-test]')?.addEventListener('click',()=>downloadText(generateTestPlan(current()),'idea-lab-test-plan.txt'));
 $('#mvp-form')?.addEventListener('submit',event=>event.preventDefault());
 $('#mvp-form')?.addEventListener('input',event=>{if(['stack','platform','notes'].includes(event.target.name)){state.mvpOptions[event.target.name]=event.target.value;persist();$('#mvp-output').value=generateMvpPrompt(current(),state.mvpOptions);}});
 $('[data-copy-mvp]')?.addEventListener('click',()=>copyText($('#mvp-output').value,$('#mvp-output')));
 $('[data-save-mvp]')?.addEventListener('click',()=>downloadText($('#mvp-output').value,'idea-lab-build-brief.txt'));
}
function connectionReady(){if(!state.settingsReady||state.settings.needsSessionSecret)return false;return state.settings.provider==='openai'?state.settings.apiKeyConfigured:state.settings.providers.some(item=>item.id===state.settings.provider&&item.available);}
async function startResearch(event){
 event.preventDefault();if(state.busy)return;const form=event.target;if(!form.reportValidity())return;
 state.draft={...defaultDraft(),...safeFields(Object.fromEntries(new FormData(form)),['idea','audience','market','goal','context'])};for(const key of Object.keys(state.draft))state.draft[key]=state.draft[key].trim();
 if(state.draft.idea.length<20){state.error='Give the idea at least 20 characters so the AI has a useful starting point.';render();return;}
 persist();await executeResearch({input:{...state.draft},mode:state.loopMode,target:state.rounds});
}
async function continueResearch(){
 const a=current();if(!a||state.busy)return;const rounds=groupRounds(a);if(rounds.at(-1)?.id!==a.id)return;
 if(a.mode==='example'){toast('This is a worked example. Try your own version to start live research.');return;}
 const round=a.loop?.round||rounds.length;if(round>=5){forkCurrent();return;}
 if(['test','stop'].includes(a.iteration.decision)&&!freshFindings(a).length&&!hasNewDirection(a)){openEvidence();return;}
 const meta=loopMeta(a),resuming=['error','paused'].includes(meta.status),mode=resuming?meta.mode||'review':'review';
 const target=Math.min(5,Math.max(round+1,resuming?Number(meta.plannedRounds)||round+1:Number(a.loop?.maxRounds)||round+1));
 await executeResearch({previous:a,target,mode,steps:mode==='auto'?target-round:1});
}
async function executeResearch({input,previous=null,target=state.rounds,mode=state.loopMode,steps=mode==='auto'?target:1}){
 if(state.busy)return;
 if(!connectionReady()){openSettings();$('#settings-message').textContent=state.settings.needsSessionSecret?'Online connection setup is not ready yet. You can still explore the examples.':'Save your AI connection, then return and run the round. Your work is saved.';return;}
 const runId=previous?groupId(previous):uid(),title=previous?.loop?.title||input.idea.slice(0,110),provider=state.settings.provider;
 runController=new AbortController();const controller=runController;
 state.busy=true;state.activeId=previous?.id||null;state.error='';state.notice='';state.mainTab='workspace';state.workspaceMode=previous?'results':'compose';
 state.run={runId,round:(previous?.loop?.round||0)+1,maxRounds:target,title,input:previous?buildIterationInput(previous):input,completed:previous?groupRounds(previous).length:0,mode,stopRequested:false};
 state.loopStates[runId]={status:'running',mode,plannedRounds:target};persist();render();
 try{
  const outcome=await runResearchLoop({input,previous,runId,title,maxRounds:target,steps,provider,signal:controller.signal,createId:uid,isValid:validAnalysis,
   analyze:async(nextInput,{signal})=>{
    const response=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...nextInput,provider}),signal:AbortSignal.any([signal,AbortSignal.timeout(state.settings.runtime==='hosted'?285000:520000)])});
    let payload;try{payload=await response.json();}catch{throw new Error('The server could not finish this round. Your completed rounds are safe; retry the next round.');}
    if(!response.ok)throw new Error(payload.error||'This round could not be completed.');return payload;
   },
   onRoundStart:({round,input:nextInput})=>{state.run.round=round;state.run.input=nextInput;render();},
   onRound:result=>{delete result.loop.exampleId;saveRound(result);state.run.completed=groupRounds(result).length;state.workspaceMode='results';state.resultTab='overview';render();}
  });
  state.loopStates[runId]={status:outcome.reason,mode,plannedRounds:target};
 }catch(error){
  const paused=controller.signal.aborted;state.loopStates[runId]={status:paused?'paused':'error',mode,plannedRounds:target};
  const hasSaved=state.analyses.some(a=>groupId(a)===runId);state.error=paused?(hasSaved?'Research stopped. Completed rounds are saved; you can resume from the next round.':'Stopped before the first round completed. Your idea is saved. Use Improve my idea to retry.'):`${error.name==='TimeoutError'?'This round took too long.':error.message||'This round could not be completed.'} Completed rounds are saved. Retry to continue where you left off.`;
 }finally{state.busy=false;state.run=null;runController=null;persist();render();}
}

function normalizeSettings(data){const hosted=data?.runtime==='hosted';return {provider:hosted?'openai':providerNames[data?.provider]?data.provider:'openai',apiKeyConfigured:data?.apiKeyConfigured===true,model:typeof data?.model==='string'?data.model:'',providers:Array.isArray(data?.providers)?data.providers.filter(item=>item&&providerNames[item.id]&&typeof item.available==='boolean'):[],runtime:hosted?'hosted':'local',storage:typeof data?.storage==='string'?data.storage:'local',needsSessionSecret:data?.needsSessionSecret===true};}
async function loadSettings(){try{const response=await fetch('/api/settings');if(!response.ok)throw new Error();state.settings=normalizeSettings(await response.json());state.settingsReady=true;}catch{state.settingsReady=false;}if($('#settings').open)renderSettings();if(!state.busy)render();}
function clearPassword(){$('#settings-key').value='';$('#settings-clear-key').checked=false;}
function openSettings(){if(state.busy){toast('Finish or stop the current investigation before changing its connection.');return;}clearPassword();state.settingsDirty=false;$('#settings-provider').value=state.settings.provider;$('#settings-model').value=state.settings.model;$('#settings-message').textContent='';$('#settings-test-message').textContent='';renderSettings();$('#settings').showModal();}
function renderSettings(){
 const hosted=state.settings.runtime==='hosted',blocked=hosted&&state.settings.needsSessionSecret;
 if(hosted)$('#settings-provider').value='openai';
 const provider=$('#settings-provider').value,status=state.settings.providers.find(item=>item.id===provider);
 for(const option of $('#settings-provider').options){option.hidden=hosted&&option.value!=='openai';option.disabled=hosted&&option.value!=='openai';}
 $('#settings-storage-intro').textContent=hosted?'Use your own OpenAI API key for this browser. Research is billed to your API account.':'Save the connection this app should use. It stays on the computer running Idea Lab.';
 $('#key-storage-info').textContent=hosted?'Key protected in an encrypted cookie for this browser. Sent only to this app’s server for research. Expires after 24 hours.':'The key is saved on the server, never in this browser’s saved investigations or build brief.';
 $('#settings-advanced-summary').textContent=hosted?'Advanced options':'Other connections and advanced options';
 $('#settings-test-explanation').textContent=hosted?'Testing checks key access without running a paid research request. It does not confirm the model’s remaining usage or research quality.':'Testing checks sign-in or key access without running a paid research request. It does not confirm the model’s remaining usage or research quality.';
 $('#api-fields').hidden=provider!=='openai';$('#subscription-help').hidden=hosted||provider==='openai';
 $('#settings-key').placeholder=state.settings.apiKeyConfigured?'Leave empty to keep your saved key':'Paste your API key';
 $('#key-state').textContent=state.settings.apiKeyConfigured?'A key is configured. It is never returned to this page.':'No API key is configured yet.';
 $('#subscription-description').textContent=provider==='codex'?'Use the official Codex app connection through its command-line tool, signed in with an eligible ChatGPT plan.':'Use the official Claude Code connection, signed in with an eligible Claude plan.';
 $('#subscription-command').textContent=provider==='codex'?'codex login':'claude auth login';
 $('#subscription-status').textContent=status?.available?'The official tool is detected. Test the saved connection to check sign-in.':'The official tool is not detected on the computer running this app.';
 $('#test-connection').disabled=state.settingsBusy||state.settingsDirty||blocked;$('#save-settings').disabled=state.settingsBusy||blocked;$('#settings-provider').disabled=state.settingsBusy||hosted;$('#settings-key').disabled=state.settingsBusy||blocked;$('#settings-model').disabled=state.settingsBusy||blocked;$('#settings-clear-key').disabled=state.settingsBusy||blocked;
 if(blocked)$('#settings-message').textContent='Online connection setup is not ready yet. You can still explore the examples.';
}
$('#settings-form').addEventListener('input',()=>{state.settingsDirty=true;$('#settings-test-message').textContent='Save changes before testing this connection.';renderSettings();});
$('#settings-provider').addEventListener('change',()=>{state.settingsDirty=true;$('#settings-test-message').textContent='Save changes before testing this connection.';renderSettings();});
$('#settings-form').addEventListener('submit',async event=>{event.preventDefault();if(state.settingsBusy||state.settings.needsSessionSecret)return;const provider=$('#settings-provider').value,payload={provider};const key=$('#settings-key').value.trim();if(provider==='openai'){if(key)payload.apiKey=key;payload.model=$('#settings-model').value.trim();}if($('#settings-clear-key').checked)payload.clearApiKey=true;state.settingsBusy=true;$('#settings-message').textContent='Saving connection…';renderSettings();try{const response=await fetch('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw new Error(data.error||'The connection could not be saved.');state.settings=normalizeSettings(data);state.settingsReady=true;state.settingsDirty=false;clearPassword();$('#settings-message').textContent='Connection saved. You can test it here, then return to your idea.';$('#settings-test-message').textContent='';render();}catch(error){$('#settings-message').textContent=error.message||'The connection could not be saved.';}finally{state.settingsBusy=false;renderSettings();}});
$('#test-connection').addEventListener('click',async()=>{if(state.settingsBusy||state.settingsDirty||state.settings.needsSessionSecret)return;state.settingsBusy=true;$('#settings-test-message').textContent='Checking sign-in and access. No research is being run…';renderSettings();try{const response=await fetch('/api/settings/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:state.settings.provider})});const data=await response.json();if(!response.ok)throw new Error(data.error||'The connection check did not pass.');$('#settings-test-message').textContent=data.message||'Connection confirmed. You can return to your idea.';}catch(error){$('#settings-test-message').textContent=error.message||'The connection could not be checked.';}finally{state.settingsBusy=false;renderSettings();}});
$('#settings').addEventListener('close',clearPassword);
$('#close-settings').addEventListener('click',()=>$('#settings').close());
document.querySelectorAll('[data-close-dialog]').forEach(el=>el.addEventListener('click',()=>$('#'+el.dataset.closeDialog).close()));
function downloadText(content,name,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
async function copyText(content,textarea,message='Build brief copied.'){try{await navigator.clipboard.writeText(content);toast(message);}catch{if(textarea?.closest('details'))textarea.closest('details').open=true;textarea?.focus();textarea?.select();toast('Select and copy the text with your keyboard; clipboard access is unavailable.');}}
function exportInvestigation(){const a=current();if(!a)return;downloadText(JSON.stringify({title:a.loop?.title||a.summary.title,rounds:groupRounds(a)},null,2),'idea-lab-backup.json','application/json');toast('All saved rounds, sources and observations exported.');}
function importBackup(value){if(state.busy)throw new Error('Stop the current investigation before restoring a backup.');const list=Array.isArray(value?.rounds)?value.rounds:[value];if(!list.length||list.length>5||!list.every(validAnalysis))throw new Error('Choose an Idea Lab backup with one to five complete rounds.');const rounds=list.map(a=>({...a,mode:'manual',provider:{id:'manual',name:'Restored backup',provenance:'user_imported'},sources:a.sources.map(item=>({...item,provenance:'user_imported'})),competitors:a.competitors.map(item=>({...item,sourceProvenance:'user_imported'})),evidence:a.evidence.map(e=>({...e,sourceProvenance:'user_imported',status:e.status!=='hypothesis'&&!safeUrl(e.sourceUrl)?'hypothesis':e.status})),limitations:[...a.limitations,'Restored from a backup. Source support and execution have not been independently verified by this app.']}));openRounds(rounds,typeof value.title==='string'?value.title.slice(0,200):rounds[0].summary.title);state.draft={...defaultDraft(),...rounds.at(-1).input};persist();$('#import-dialog').close();toast('Backup restored. Your rounds and observations are available.');}
$('#choose-import-file').addEventListener('click',()=>$('#import-file').click());
$('#import-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>3000000)throw new Error('Choose a backup smaller than 3 MB.');importBackup(JSON.parse(await file.text()));}catch(error){$('#import-error').textContent=error instanceof SyntaxError?'This file is not a valid Idea Lab backup.':error.message;}event.target.value='';});
$('#evidence-form').addEventListener('submit',event=>{event.preventDefault();const a=current();if(!a||state.busy)return;const data=Object.fromEntries(new FormData(event.target));if(data.claim.trim().length<12||!data.note.trim()){toast('Add a concrete observation and its context.');return;}if(a.evidence.length>=150){toast('This evidence ledger is full. Save a backup before starting another investigation.');return;}a.evidence.push({id:uid(),addedAfterRound:a.id,claim:data.claim.trim(),status:'hypothesis',sourceUrl:safeUrl(data.sourceUrl),sourceTitle:'User-provided source',observedAt:new Date().toISOString().slice(0,10),note:data.note.trim(),userProvided:true});persist();$('#evidence-dialog').close();event.target.reset();render();toast('Observation saved. It will accompany the next refinement.');});
window.addEventListener('beforeunload',event=>{if(state.busy){event.preventDefault();event.returnValue='';}});
render();loadSettings();
